/**
 * memory_search tool: Agent-callable tool for searching L1 memory records.
 *
 * Supports three search strategies with automatic degradation:
 *   1. **hybrid** (default) — FTS5 keyword + vector embedding in parallel,
 *      merged via Reciprocal Rank Fusion (RRF).
 *   2. **embedding** — pure vector similarity (when FTS5 is unavailable).
 *   3. **fts** — pure FTS5 keyword search (when embedding is unavailable).
 *
 * The tool is registered via `api.registerTool()` in index.ts.
 */

import type { IMemoryStore } from "../store/types.js";
import { buildFtsQuery } from "../store/sqlite.js";
import type { EmbeddingService } from "../store/embedding.js";
import { readAllMemoryRecords } from "../record/l1-reader.js";
import { sanitizeText } from "../utils/sanitize.js";

// ============================
// Types
// ============================

interface Logger {
  debug?: (message: string) => void;
  info: (message: string) => void;
  warn: (message: string) => void;
  error: (message: string) => void;
}

export interface MemorySearchResultItem {
  id: string;
  content: string;
  type: string;
  priority: number;
  scene_name: string;
  score: number;
  created_at: string;
  updated_at: string;
}

export interface MemorySearchResult {
  results: MemorySearchResultItem[];
  total: number;
  strategy: string;
  /** Optional message, e.g. when embedding is not configured. */
  message?: string;
}

const TAG = "[memory-tdai][tdai_memory_search]";

// ============================
// RRF (Reciprocal Rank Fusion)
// ============================

/** Standard RRF constant from the original RRF paper. */
const RRF_K = 60;

/**
 * Merge multiple ranked lists of `MemorySearchResultItem` via Reciprocal Rank
 * Fusion. Items appearing in multiple lists get their RRF scores summed.
 *
 * Returns items sorted by descending RRF score. The `score` field of each
 * returned item is replaced by the RRF score for consistent ranking semantics.
 */
function rrfMergeL1(...lists: MemorySearchResultItem[][]): MemorySearchResultItem[] {
  const map = new Map<string, { item: MemorySearchResultItem; rrfScore: number }>();

  for (const list of lists) {
    for (let rank = 0; rank < list.length; rank++) {
      const item = list[rank];
      const score = 1 / (RRF_K + rank + 1);
      const existing = map.get(item.id);
      if (existing) {
        existing.rrfScore += score;
      } else {
        map.set(item.id, { item, rrfScore: score });
      }
    }
  }

  return [...map.values()]
    .sort((a, b) => b.rrfScore - a.rrfScore)
    .map(({ item, rrfScore }) => ({ ...item, score: rrfScore }));
}

// ============================
// Search implementation
// ============================

export async function executeMemorySearch(params: {
  query: string;
  limit: number;
  type?: string;
  scene?: string;
  pluginDataDir?: string;
  vectorStore?: IMemoryStore;
  embeddingService?: EmbeddingService;
  logger?: Logger;
}): Promise<MemorySearchResult> {
  const {
    query,
    limit,
    type: typeFilter,
    scene: sceneFilter,
    pluginDataDir,
    vectorStore,
    logger,
  } = params;

  logger?.debug?.(
    `${TAG} CALLED: query="${query.slice(0, 100)}", limit=${limit}, ` +
    `typeFilter=${typeFilter ?? "(none)"}, sceneFilter=${sceneFilter ?? "(none)"}, ` +
    `vectorStore=${vectorStore ? "available" : "UNAVAILABLE"}`,
  );

  if (!query || query.trim().length === 0) {
    logger?.debug?.(`${TAG} Empty query, returning empty`);
    return { results: [], total: 0, strategy: "none" };
  }

  if (!vectorStore) {
    logger?.warn?.(`${TAG} VectorStore not available`);
    return { results: [], total: 0, strategy: "none" };
  }

  // 按当前策略：不走 embedding，仅使用 FTS（不可用时再走 JSONL）。
  const hasFts = vectorStore.isFtsAvailable();
  if (!hasFts) {
    logger?.warn?.(`${TAG} FTS unavailable, trying JSONL fallback`);
    if (pluginDataDir) {
      const fallback = await searchJsonlKeywordFallback({
        query,
        limit,
        typeFilter,
        sceneFilter,
        pluginDataDir,
        logger,
      });
      if (fallback.results.length > 0) return fallback;
    }
    return {
      results: [],
      total: 0,
      strategy: "none",
      message:
        "FTS is not available and JSONL fallback returned no matches.",
    };
  }

  // ── Over-retrieve for later filtering and RRF merging ──
  const candidateK = limit * 3;

  let results: MemorySearchResultItem[] = [];
  try {
    const ftsQuery = buildFtsQuery(query);
    if (!ftsQuery) {
      logger?.debug?.(`${TAG} [fts] No usable FTS tokens from query`);
      return { results: [], total: 0, strategy: "fts" };
    }
    logger?.debug?.(`${TAG} [fts] FTS5 query: "${ftsQuery}"`);
    const ftsResults = await vectorStore.searchL1Fts(ftsQuery, candidateK);
    logger?.debug?.(`${TAG} [fts] FTS5 returned ${ftsResults.length} candidates`);
    results = ftsResults.map((r) => ({
      id: r.record_id,
      content: r.content,
      type: r.type,
      priority: r.priority,
      scene_name: r.scene_name,
      score: r.score,
      created_at: r.timestamp_start,
      updated_at: r.timestamp_end,
    }));
  } catch (err) {
    logger?.warn?.(`${TAG} [fts] Search failed (non-fatal): ${err instanceof Error ? err.message : String(err)}`);
    return { results: [], total: 0, strategy: "fts" };
  }

  // ── Apply secondary filters (type, scene) ──
  const preFilterCount = results.length;
  if (typeFilter) {
    results = results.filter((r) => r.type === typeFilter);
    logger?.debug?.(`${TAG} After type filter "${typeFilter}": ${results.length}/${preFilterCount}`);
  }
  if (sceneFilter) {
    const normalizedScene = sceneFilter.toLowerCase();
    results = results.filter((r) =>
      r.scene_name.toLowerCase().includes(normalizedScene),
    );
    logger?.debug?.(`${TAG} After scene filter "${sceneFilter}": ${results.length}/${preFilterCount}`);
  }

  // ── Trim to requested limit ──
  const trimmed = results.slice(0, limit);

  logger?.debug?.(
    `${TAG} RESULT (strategy=fts): returning ${trimmed.length} memories ` +
    `(scores: [${trimmed.map((r) => r.score.toFixed(3)).join(", ")}])`,
  );

  return {
    results: trimmed,
    total: trimmed.length,
    strategy: "fts",
  };
}

async function searchJsonlKeywordFallback(params: {
  query: string;
  limit: number;
  typeFilter?: string;
  sceneFilter?: string;
  pluginDataDir: string;
  logger?: Logger;
}): Promise<MemorySearchResult> {
  const { query, limit, typeFilter, sceneFilter, pluginDataDir, logger } = params;
  const cleanQuery = sanitizeText(query).trim();
  if (!cleanQuery) return { results: [], total: 0, strategy: "jsonl_keyword" };

  const ftsLikeQuery = buildFtsQuery(cleanQuery);
  const tokens = extractKeywordTokens(cleanQuery, ftsLikeQuery);
  if (tokens.length === 0) return { results: [], total: 0, strategy: "jsonl_keyword" };

  const records = await readAllMemoryRecords(pluginDataDir, logger);
  if (records.length === 0) return { results: [], total: 0, strategy: "jsonl_keyword" };

  const normalizedScene = sceneFilter?.toLowerCase().trim();
  const scored = records
    .map((record) => {
      if (typeFilter && record.type !== typeFilter) return null;
      if (normalizedScene && !record.scene_name.toLowerCase().includes(normalizedScene)) return null;
      const haystack = `${record.content} ${record.scene_name} ${record.type}`.toLowerCase();
      const score = scoreByKeywordTokens(haystack, tokens);
      if (score <= 0) return null;
      return {
        id: record.id,
        content: record.content,
        type: String(record.type),
        priority: record.priority,
        scene_name: record.scene_name,
        score,
        created_at: record.createdAt,
        updated_at: record.updatedAt,
      } as MemorySearchResultItem;
    })
    .filter((item): item is MemorySearchResultItem => !!item)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit);

  return { results: scored, total: scored.length, strategy: "jsonl_keyword" };
}

function extractKeywordTokens(cleanQuery: string, ftsLikeQuery: string | null): string[] {
  if (ftsLikeQuery) {
    const quotedTokens = [...ftsLikeQuery.matchAll(/"([^"]+)"/g)]
      .map((m) => m[1]?.trim().toLowerCase() ?? "")
      .filter(Boolean);
    const deduped = [...new Set(quotedTokens)];
    if (deduped.length > 0) return deduped;
  }
  const fallbackTokens = cleanQuery
    .toLowerCase()
    .match(/[\p{L}\p{N}_]+/gu)
    ?.map((t) => t.trim())
    .filter(Boolean) ?? [];
  return [...new Set(fallbackTokens)];
}

function scoreByKeywordTokens(haystackLower: string, tokens: string[]): number {
  let matchedTokenCount = 0;
  let totalHits = 0;
  for (const token of tokens) {
    if (!token) continue;
    const hitCount = haystackLower.split(token).length - 1;
    if (hitCount > 0) {
      matchedTokenCount += 1;
      totalHits += hitCount;
    }
  }
  if (matchedTokenCount === 0) return 0;
  const coverage = matchedTokenCount / tokens.length;
  const density = Math.log1p(totalHits) / 5;
  return coverage + density;
}

// ============================
// Tool response formatter
// ============================

export function formatSearchResponse(result: MemorySearchResult): string {
  if (result.message) {
    return result.message;
  }
  if (result.results.length === 0) {
    return "No matching memories found.";
  }

  const lines: string[] = [
    `Found ${result.total} matching memories:`,
    "",
  ];

  for (const item of result.results) {
    const scoreStr = typeof item.score === "number" ? ` (score: ${item.score.toFixed(3)})` : "";
    const sceneStr = item.scene_name ? ` [scene: ${item.scene_name}]` : "";
    const priorityStr = item.priority >= 0 ? ` (priority: ${item.priority})` : " (global instruction)";
    lines.push(`- **[${item.type}]**${priorityStr}${sceneStr}${scoreStr}`);
    lines.push(`  ${item.content}`);
    lines.push("");
  }

  return lines.join("\n");
}
